commands.podman exec web cat /etc/nginx/nginx.con:
worker_processes  auto;
events {
    worker_connections  1024;
}
http {
    server {
        listen       80;
        server_name  localhost;
        location / {
            root   /usr/share/nginx/html;
            index  index.html;
        }
        location /healthz {
            return 200 'ok';
        }
    }
}
